send_js:
const ta = document.querySelector('textarea#chat-input, textarea[placeholder], textarea');
if (!ta) return 'ERR:no input';
ta.focus();
Object.getOwnPropertyDescriptor(HTMLTextAreaElement.prototype, 'value').set.call(ta, PROMPT);
ta.dispatchEvent(new Event('input', {bubbles: true}));
await new Promise(r => setTimeout(r, 300));
ta.dispatchEvent(new KeyboardEvent('keydown', {key:'Enter', code:'Enter', keyCode:13, which:13, bubbles:true, cancelable:true}));
ta.dispatchEvent(new KeyboardEvent('keyup', {key:'Enter', code:'Enter', keyCode:13, which:13, bubbles:true}));
return 'sent';

extract_js:
const els = document.querySelectorAll('.ds-markdown, .markdown-body, [class*="markdown"]');
if (!els.length) return '';
return (els[els.length - 1].innerText || '').trim();
